namespace ZoneEngine.Core.Arete.Quests
{
    using System;

    using AORebirth.Core.Entities;
    using AORebirth.Core.Network;

    using Utility;

    using ZoneEngine.Core.Controllers;

    /// <summary>
    /// Capture 20260801-Desmond Calitri QuestFullUpdate wire tips.
    /// Capture AbsoluteTime values are intentionally preserved.
    /// </summary>
    internal static class DesmondCalitriTipSender
    {
        public const int BurgerTipInstance = unchecked((int)0x5576B750);
        public const int RallyTipInstance = unchecked((int)0x5576B755);
        public const int ReturnTipInstance = unchecked((int)0x5576B758);
        public const int WetworkTipInstance = unchecked((int)0x5576B75C);

        private const int CapturedPlayerInstance = unchecked((int)0x79B0C81A);

        private const string BurgerTipHex =
            "";

        private const string RallyTipHex =
            "";

        private const string ReturnTipHex =
            "";

        private const string WetworkTipHex =
            "";

        public static RexQuestPreviewEmissionResult TrySendBurgerTipOnly(ICharacter source)
        {
            return TipOnly(source, BurgerTipHex, "DesmondBurger", "Mission:5576B750");
        }

        public static RexQuestPreviewEmissionResult TrySendBurgerToRallyHandoff(ICharacter source)
        {
            return Handoff(source, BurgerTipInstance, RallyTipHex, "DesmondBurger→Rally", "Mission:5576B755");
        }

        public static RexQuestPreviewEmissionResult TrySendRallyToReturnHandoff(ICharacter source)
        {
            return Handoff(source, RallyTipInstance, ReturnTipHex, "DesmondRally→Return", "Mission:5576B758");
        }

        public static RexQuestPreviewEmissionResult TrySendReturnToWetworkHandoff(ICharacter source)
        {
            return Handoff(source, ReturnTipInstance, WetworkTipHex, "DesmondReturn→Wetwork", "Mission:5576B75C");
        }

        public static void DeleteWetworkTip(ICharacter source)
        {
            SafeQuestFullUpdateSender.SendTipAction59AndDelete(source, WetworkTipInstance);
        }

        private static RexQuestPreviewEmissionResult Handoff(
            ICharacter source,
            int deleteMissionInstance,
            string nextHex,
            string label,
            string questId)
        {
            if (source?.Controller?.Client == null)
            {
                return RexQuestPreviewEmissionResult.Failed(label + " skipped: client missing.");
            }

            try
            {
                SafeQuestFullUpdateSender.SendTipAction59AndDelete(source, deleteMissionInstance);
                if (!TrySendWire(source, nextHex))
                {
                    return RexQuestPreviewEmissionResult.Failed(label + " tip wire failed after delete.");
                }

                return RexQuestPreviewEmissionResult.Sent(label + " tip. mission=" + questId);
            }
            catch (Exception ex)
            {
                return RexQuestPreviewEmissionResult.Failed(label + " failed: " + ex.Message);
            }
        }

        private static RexQuestPreviewEmissionResult TipOnly(
            ICharacter source,
            string tipHex,
            string label,
            string questId)
        {
            if (source?.Controller?.Client == null)
            {
                return RexQuestPreviewEmissionResult.Failed(label + " skipped: client missing.");
            }

            try
            {
                return TrySendWire(source, tipHex)
                           ? RexQuestPreviewEmissionResult.Sent(label + " tip. mission=" + questId)
                           : RexQuestPreviewEmissionResult.Failed(label + " tip wire failed.");
            }
            catch (Exception ex)
            {
                return RexQuestPreviewEmissionResult.Failed(label + " failed: " + ex.Message);
            }
        }

        private static bool TrySendWire(ICharacter source, string hex)
        {
            ZoneClient client = source?.Controller?.Client as ZoneClient;
            if (client == null || source.Identity.Instance == 0)
            {
                return false;
            }

            byte[] packet = HexToBytes(hex);
            ReplaceInt32Be(packet, CapturedPlayerInstance, source.Identity.Instance);
            client.EnqueueOutboundCompressedBuffer(packet);
            LogUtil.Debug(
                DebugInfoDetail.Engine,
                "DesmondCalitriTipSender wire enqueued bytes="
                + packet.Length
                + " character="
                + source.Identity.ToString(true)
                + " patchAbsTime=False");
            return true;
        }

        private static byte[] HexToBytes(string hex)
        {
            byte[] bytes = new byte[hex.Length / 2];
            for (int i = 0; i < bytes.Length; i++)
            {
                bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
            }

            return bytes;
        }

        private static void ReplaceInt32Be(byte[] packet, int from, int to)
        {
            byte b0 = (byte)(from >> 24);
            byte b1 = (byte)(from >> 16);
            byte b2 = (byte)(from >> 8);
            byte b3 = (byte)from;
            for (int i = 0; i + 4 <= packet.Length; i++)
            {
                if (packet[i] == b0 && packet[i + 1] == b1 && packet[i + 2] == b2 && packet[i + 3] == b3)
                {
                    packet[i] = (byte)(to >> 24);
                    packet[i + 1] = (byte)(to >> 16);
                    packet[i + 2] = (byte)(to >> 8);
                    packet[i + 3] = (byte)to;
                    i += 3;
                }
            }
        }
    }
}
